from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with shared memory and loop unrolling
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1];  // +1 to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t += UNROLL_FACTOR) {
        // Preload multiple tiles to enable loop unrolling
        for (int i = 0; i < UNROLL_FACTOR; i++) {
            int t_idx = t + i;
            if (t_idx < (N + TILE_SIZE - 1) / TILE_SIZE) {
                // Load tile of A into shared memory
                int a_col = t_idx * TILE_SIZE + tx;
                if (row < N && a_col < N) {
                    As[ty][tx] = A[row * N + a_col];
                } else {
                    As[ty][tx] = 0.0f;
                }

                // Load tile of B into shared memory
                int b_row = t_idx * TILE_SIZE + ty;
                if (b_row < N && col < N) {
                    Bs[ty][tx] = B[b_row * N + col];
                } else {
                    Bs[ty][tx] = 0.0f;
                }
            }
            __syncthreads();

            // Compute partial sums for multiple tiles
            for (int k = 0; k < TILE_SIZE; k++) {
                sum += As[ty][k] * Bs[k][tx];
            }
            __syncthreads();
        }
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check input dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions must match");

    int M = A.size(0);
    int N = A.size(1);
    int P = B.size(1);

    auto C = torch::zeros({M, P}, torch::TensorOptions().dtype(A.dtype()).device(A.device()));

    // Use 16x16 thread blocks
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((P + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

